'use strict';
const $=id=>document.getElementById(id), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const clone=x=>structuredClone(x);
const names={title:'论文标题',...Object.fromEntries(Array.from({length:9},(_,i)=>['heading'+(i+1),`${i+1} 级标题`])),author:'作者信息',body:'正文',abstract:'摘要',keywords:'关键词',caption:'图表题注',note:'表注 / 资料来源',reference:'参考文献'};
const FONT_CHOICES=['宋体','SimSun','宋体-简','黑体','SimHei','黑体-简','微软雅黑','Microsoft YaHei','微软雅黑 UI','等线','DengXian','仿宋','FangSong','仿宋_GB2312','楷体','KaiTi','楷体_GB2312','华文中宋','华文宋体','华文仿宋','华文楷体','华文黑体','华文细黑','华文行楷','华文隶书','苹方-简','PingFang SC','冬青黑体简体中文','兰亭黑-简','思源黑体','思源宋体','Noto Sans CJK SC','Noto Serif CJK SC','Times New Roman','Arial','Arial Narrow','Arial Black','Arial Unicode MS','Aptos','Aptos Display','Calibri','Calibri Light','Cambria','Cambria Math','Century Gothic','Consolas','Courier New','Garamond','Georgia','Helvetica','Helvetica Neue','Menlo','Monaco','Palatino Linotype','Segoe UI','Tahoma','Trebuchet MS','Verdana'];
const FONT_SIZES=[['5','八号'],['5.5','七号'],['6.5','小六'],['7.5','六号'],['8','常用'],['9','小五'],['9.5','常用'],['10','常用'],['10.5','五号'],['11','常用'],['12','小四'],['12.5','常用'],['14','四号'],['15','小三'],['16','三号'],['18','小二'],['20','常用'],['21','常用'],['22','二号'],['24','小一'],['26','一号'],['28','常用'],['36','小初'],['42','初号'],['48','常用'],['72','常用']];
const S={docs:[],current:null,profile:null,defaults:null,tab:'styles',styleKey:'heading1',styleScope:'all',tableScope:'current',pid:null,tid:null,cell:null,eid:null,mode:'after',zoom:.9,busy:false,undo:[],redo:[],journals:[],formulaDraft:'',formulaValidated:false,deepseekConnected:false,preflighting:false};
const doc=()=>S.docs.find(d=>d.id===S.current), para=()=>doc()?.model.paragraphs.find(p=>p.id===S.pid), table=()=>doc()?.model.tables.find(t=>t.id===S.tid);
const currentRole=()=>doc()?.roles[S.pid]||para()?.role;
function toast(text,error=false){const n=document.createElement('div');n.className='toast'+(error?' error':'');n.textContent=text;$('toasts').append(n);setTimeout(()=>n.remove(),6000)}
async function api(path,payload){const r=await fetch('/api/'+path,payload?{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)}:{});const data=await r.json();if(!r.ok)throw Error(data.error||'操作失败');return data}
function showDeepseekStatus(s){S.deepseekConnected=!!s.connected;const n=$('deepseekStatus');n.classList.toggle('connected',s.connected);n.innerHTML=`<span class="status-dot"></span><div><b>${s.connected?'已连接 · '+esc(s.model):'尚未连接'}</b><p>${s.serverManaged?(s.configured?'密钥由课程服务器管理；点击连接并测试后可使用 AI。':'请由组员在课程上传页面配置服务器密钥。'):(s.connected?'连接测试通过；本次服务运行期间密钥保存在本机内存。':'连接后可用于下一步的文章结构识别。')}</p></div>`;document.querySelector('.api-key-field').hidden=!!s.serverManaged;document.querySelector('.api-note').textContent=s.serverManaged?'课程服务器密钥由小组在上传管理页配置，不要在这里输入密钥。连接测试只发送简短消息。':'密钥只保存在本机服务内存中，重启服务后需重新输入。连接测试只发送一条简短消息。';$('disconnectDeepseek').disabled=!!s.serverManaged||!s.connected;if(s.connected)$('deepseekModel').value=s.model;if(S.tab==='ai'&&$('inspectorBody'))renderInspector()}
async function loadDeepseekStatus(){try{showDeepseekStatus(await api('deepseek/status'))}catch(e){showDeepseekStatus({connected:false})}}
async function connectDeepseek(){const b=$('connectDeepseek');b.disabled=true;b.textContent='正在连接…';try{const s=await api('deepseek/connect',{key:$('deepseekKey').value,model:$('deepseekModel').value});$('deepseekKey').value='';showDeepseekStatus(s);toast('DeepSeek 连接测试通过；本次尚未向 API 发送论文内容')}catch(e){toast(e.message,true)}finally{b.disabled=false;b.textContent='连接并测试'}}
async function disconnectDeepseek(){try{showDeepseekStatus(await api('deepseek/disconnect',{}));$('deepseekKey').value='';toast('已清除本机内存中的 DeepSeek 密钥')}catch(e){toast(e.message,true)}}
function busy(value,label='正在处理…'){S.busy=value;$('busy').hidden=!value;$('busyText').textContent=label;$('workspace').inert=value;document.querySelectorAll('.top-actions button,.tools button').forEach(b=>b.disabled=value);if(!value){updateActions();if(S.tab==='quality')renderInspector()}}
function snapshot(){return {profile:clone(S.profile),documents:S.docs.map(d=>({id:d.id,roles:clone(d.roles),aiLocks:clone(d.aiLocks||{}),overrides:clone(d.overrides),tables:clone(d.tables),equations:clone(d.equations),insertions:clone(d.insertions)}))}}
function remember(){S.undo.push(snapshot());if(S.undo.length>35)S.undo.shift();S.redo=[]}
function invalidate(all=true){for(const d of all?S.docs:[doc()].filter(Boolean)){d.result=null;d.report=null}S.formulaValidated=false;updateActions()}
function restore(s){S.profile=clone(s.profile);for(const sd of s.documents){const d=S.docs.find(d=>d.id===sd.id);if(d)Object.assign(d,clone(sd))}invalidate();render()}
function undo(){if(S.busy||!S.undo.length)return;S.redo.push(snapshot());restore(S.undo.pop());toast('已撤销上一步设置')}
function redo(){if(S.busy||!S.redo.length)return;S.undo.push(snapshot());restore(S.redo.pop());toast('已重做设置')}
function updateActions(){const d=doc();$('runBtn').disabled=S.busy||!S.docs.length;$('downloadBtn').disabled=S.busy||!d?.result;$('downloadBtn').textContent=isResultStale(d)?'下载先前输出':'下载 DOCX';$('undoBtn').disabled=S.busy||!S.undo.length;$('redoBtn').disabled=S.busy||!S.redo.length;$('health').textContent=S.courseMode?'课程服务器 · 已连接':'本机引擎 · 已连接';window.DocStyleWorkflow?.changed()}
function blobDownload(blob,name){const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),6000)}
function downloadResult(){const d=doc();if(!d?.result)return;const bytes=Uint8Array.from(atob(d.result),c=>c.charCodeAt(0));blobDownload(new Blob([bytes],{type:'application/vnd.openxmlformats-officedocument.wordprocessingml.document'}),d.name.replace(/\.docx$/i,'')+'_DocStyle_v5.docx')}
function downloadReport(){const d=doc();if(!d?.report)return;blobDownload(new Blob([JSON.stringify(d.report,null,2)],{type:'application/json'}),d.name.replace(/\.docx$/i,'')+'_排版报告.json')}
function settings(d){return {id:d.id,profile:clone(S.profile),roles:d.roles,locks:d.aiLocks||{},classificationReview:{sourceMode:d.aiSummary?.sourceMode||'manual',liveVerified:!!d.aiSummary?.liveVerified,model:d.aiSummary?.model,items:(d.aiCandidates||[]).map(({id,role,reason,confidence,locked})=>({id,role,reason,confidence,locked:!!(d.aiLocks?.[id]||locked)}))},overrides:d.overrides,tables:d.tables,equations:d.equations,insertions:d.insertions}}
function settingsSignature(value){const clean=key=>['profile','roles','overrides','tables','equations','insertions'].includes(key);const selected={};for(const [key,item] of Object.entries(value||{}))if(clean(key)){selected[key]=clone(item);if(key==='profile')for(const ignored of ['ruleLedger','source','schemaVersion','version'])delete selected[key][ignored]}const stable=x=>Array.isArray(x)?x.map(stable):x&&typeof x==='object'?Object.fromEntries(Object.keys(x).sort().map(k=>[k,stable(x[k])])):x;return JSON.stringify(stable(selected))}
function isResultStale(d){return !!(d?.result&&d.report?.settings&&settingsSignature(d.report.settings)!==settingsSignature(settings(d)))}
function addDocument(data){S.docs.push({...data,roles:{},aiLocks:{},overrides:{},tables:{},equations:{},insertions:[],result:null,report:null});S.current=data.id;S.pid=null;S.tid=data.model.tables[0]?.id||null;S.cell=null;S.eid=data.model.equations[0]?.id||null;S.styleScope='all';S.undo=[];S.redo=[];render()}
async function loadSample(){if(S.busy)return;busy(true,'载入演示文档');try{addDocument(await api('sample'));toast('已载入含合并表头、4 级标题与原生公式的演示文档')}catch(e){toast(e.message,true)}finally{busy(false)}}
function fileData(file){return new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result.split(',')[1]);r.onerror=()=>reject(Error('无法读取文件'));r.readAsDataURL(file)})}
async function importFiles(files){if(S.busy)return;busy(true,'读取 Word 文档');let count=0;for(const file of files){try{if(!/\.docx$/i.test(file.name))throw Error('请选择 DOCX 文件');if(file.size>30*1024*1024)throw Error('单份文件请小于 30 MB');addDocument(await api('import',{name:file.name,data:await fileData(file)}));count++}catch(e){toast(file.name+'：'+e.message,true)}}busy(false);if(count)toast(`已导入 ${count} 份文档；点击页面中的内容可单独调整`)}
async function run(all=false){if(S.busy||S.preflighting||!doc())return;if(all&&window.DocStyleWorkflow){window.DocStyleWorkflow.open('batch');return;}for(const field of $('inspectorBody').querySelectorAll('[data-setting]')){try{changedValue(field)}catch(e){field.focus();toast(e.message,true);return}}const queue=all?[...S.docs]:[doc()];S.preflighting=true;try{if(!window.DocStyleWorkflow||!await window.DocStyleWorkflow.preflight(queue))return;}finally{S.preflighting=false}busy(true,'正在写入格式并逐项检查');let completed=0;for(const d of queue){try{const out=await api('format',settings(d));d.result=out.data;d.report=out.report;completed++}catch(e){d.result=null;d.report=null;toast(d.name+'：'+e.message,true)}}S.tab='quality';render();busy(false);if(completed)toast(`已生成 ${completed} 份新输出。请查看检查报告中的通过项与待复核项。`)}
function setTab(tab){S.tab=tab;if(tab==='tables'&&!S.tid)S.tid=doc()?.model.tables[0]?.id;if(tab==='equations'&&!S.eid)S.eid=doc()?.model.equations[0]?.id||null;renderInspector();$('inspectorBody').scrollTop=0;renderNav()}
function renderNav(){document.querySelectorAll('[data-tab]').forEach(b=>b.classList.toggle('active',b.dataset.tab===S.tab))}
function renderFiles(){ $('fileList').innerHTML=S.docs.length?S.docs.map(d=>`<div class="file-row ${d.id===S.current?'active':''}"><button class="file-choice" data-doc="${d.id}" title="${esc(d.name)}"><span class="file-icon">▤</span><span><b>${esc(d.name)}</b><small>${d.model.counts.paragraphs} 段 · ${isResultStale(d)?'先前设置的输出':d.report?'已检查':'待排版'}</small></span></button><button class="file-close" data-remove="${d.id}" aria-label="移除 ${esc(d.name)}">×</button></div>`).join(''):'<p class="outline-empty">暂未打开文档</p>'}
function renderOutline(){const d=doc();const p=d?.model.paragraphs.filter(p=>{const role=d.roles[p.id]||p.role;return role==='title'||role.startsWith('heading')})||[];$('outlineCount').textContent=p.length?`${p.length} 项`:'';$('outline').innerHTML=p.length?p.map(p=>{const r=d.roles[p.id]||p.role;const level=r==='title'?0:Number(r.slice(7));return `<button class="${p.id===S.pid?'active':''}" data-outline="${p.id}" style="padding-left:${7+Math.min(level,5)*7}px" title="${esc(p.text)}">${esc(p.text)}</button>`}).join(''):'<div class="outline-empty">导入后显示识别出的标题</div>'}
function selectParagraph(id,scroll=false){S.pid=id;S.cell=null;S.styleScope='paragraph';const role=currentRole();if(names[role]){S.styleKey=role;S.tab='styles'}else if(role==='equation'){S.tab='equations';S.eid=para()?.equations[0]||null}else if(role==='cell'){S.tab='tables'}renderInspector();renderNav();renderOutline();renderPreview();if(scroll)document.querySelector(`[data-pid="${id}"]`)?.scrollIntoView({behavior:'smooth',block:'center'})}
function render(){renderFiles();renderOutline();renderNav();renderPreview();renderInspector();updateActions()}
function safeFont(v){return String(v||'宋体').replace(/[\u0000-\u001f\u007f]/g,'').replace(/\\/g,'\\\\').replace(/"/g,'\\"')}
function previewRules(base,override={}){const rule={...base,...override},states={...base?._fieldStates,...override._fieldStates};for(const group of [['line','lineMode'],['indent','indentMode','indentUnit']]){const special=group.map(k=>states[k]).find(v=>['preserve','clear','unspecified'].includes(v));if(special)for(const key of group)states[key]=special}return Object.fromEntries(Object.entries(rule).filter(([k])=>k!=='_fieldStates'&&!['preserve','clear','unspecified'].includes(states[k])))}
function effectiveParagraph(p){const d=doc();if(S.mode==='before')return p.format;const role=d.roles[p.id]||p.role;const s=S.profile.styles[role];return {...p.format,...previewRules(s?.enabled?s:{},d.overrides[p.id]||{})}}
function cssStyle(s){const scale=S.zoom,pt=(s.size||10.5)*1.333*scale;const out=[`font-family:"${safeFont(s.font)}","${safeFont(s.latin)}",serif`,`font-size:${pt}px`,`text-align:${s.align==='both'?'justify':s.align||'left'}`];if(s.bold!==null&&s.bold!==undefined)out.push(`font-weight:${s.bold?'700':'400'}`);if(s.italic!==null&&s.italic!==undefined)out.push(`font-style:${s.italic?'italic':'normal'}`);if(s.underline!==null&&s.underline!==undefined)out.push(`text-decoration:${s.underline?'underline':'none'}`);if(s.color&&/^[a-f\d]{6}$/i.test(s.color))out.push('color:#'+s.color);out.push(`line-height:${s.lineMode==='exact'?s.line*1.333*scale+'px':s.lineMode==='atLeast'?Math.max(pt*1.2,s.line*1.333*scale)+'px':s.line||1.5}`,`margin-top:${(s.before||0)*1.333*scale}px`,`margin-bottom:${(s.after||0)*1.333*scale}px`,`padding-left:${(s.left||0)*37.8*scale}px`,`padding-right:${(s.right||0)*37.8*scale}px`);const indent=s.indentMode==='none'?0:(s.indent||0)*(s.indentUnit==='chars'?pt:37.8*scale);out.push(`text-indent:${s.indentMode==='hanging'?-indent:indent}px`);if(s.indentMode==='hanging')out.push(`margin-left:${indent}px`);return out.join(';')}
function mathHtml(e){const d=doc(),edit=S.mode==='after'&&d.equations[e.id],latex=edit?.latex??e.latex,global=S.profile.equation;const active=global?.enabled&&(global.scope==='all'||!global.scope||(global.scope==='display')===!!e.display);const rule=S.mode==='after'?previewRules(active?global:{},edit?.format||{}):{};const css=[];if(rule.size)css.push(`font-size:${Number(rule.size)*1.333*S.zoom}px`);if(rule.color&&/^[a-f\d]{6}$/i.test(rule.color))css.push(`color:#${rule.color}`);if(e.unsupported?.length)return `<span class="formula-unsupported" data-equation="${esc(e.id)}">原生公式 · 含复杂结构，点击查看</span>`;return `<span class="formula-view" data-equation="${esc(e.id)}" title="点击编辑公式"><math-field read-only tabindex="-1" style="${esc(css.join(';'))}">${esc(latex)}</math-field></span>`}
function paragraphHtml(p){const d=doc(),role=d.roles[p.id]||p.role,s=effectiveParagraph(p);let content=p.segments?.map(seg=>{if(seg.kind==='equation'){const e=d.model.equations.find(e=>e.id===seg.id);return e?mathHtml(e):''}const fmt={...seg.format};if(S.mode==='after'){const rule=S.profile.styles[role];const override=d.overrides[p.id]||{};const applied=previewRules(rule?.enabled?rule:{},override);for(const k of ['bold','italic','underline','color'])if(applied[k]!==null&&applied[k]!==undefined)fmt[k]=applied[k]}const styles=[];if(fmt.bold!==undefined)styles.push(`font-weight:${fmt.bold?'700':'400'}`);if(fmt.italic!==undefined)styles.push(`font-style:${fmt.italic?'italic':'normal'}`);if(fmt.underline!==undefined)styles.push(`text-decoration:${fmt.underline?'underline':'none'}`);if(fmt.color&&/^[a-f\d]{6}$/i.test(fmt.color))styles.push('color:#'+fmt.color);return String(seg.text).split(/([\u0000-\u024f]+)/).filter(Boolean).map(text=>{const font=/^[\u0000-\u024f]+$/.test(text)?s.latin:s.font;return `<span style="${esc(styles.join(';')+(font?`;font-family:"${safeFont(font)}",serif`:''))}">${esc(text)}</span>`}).join('')}).join('')??esc(p.text);const latexCandidate=d.model.equations.find(e=>e.paragraph===p.id&&e.kind==='latex_text');if(S.mode==='after'&&latexCandidate&&d.equations[latexCandidate.id]?.convertLatex)content=mathHtml(latexCandidate);const embedded=d.model.equations.filter(e=>e.paragraph===p.id&&e.kind==='mathtype_ole');content+=embedded.map(e=>`<span class="formula-unsupported" data-equation="${esc(e.id)}">嵌入公式对象 · 点击查看</span>`).join('');content+=p.images.map(src=>`<img src="${src}" alt="文档原图">`).join('');if(!content)content='&nbsp;';let style=cssStyle(s);if(role==='equation'){const eq=S.profile.equation;style+=`;text-align:${S.mode==='after'&&eq.enabled?eq.align:'center'};text-indent:0;`;if(S.mode==='after'&&eq.enabled)style+=`margin-top:${eq.before*1.2}px;margin-bottom:${eq.after*1.2}px;`}
return `<div class="doc-par ${S.pid===p.id?'selected':''}" data-pid="${p.id}" data-label="${esc(names[role]||'原生公式')}" style="${esc(style)}">${content}</div>`}
function effectiveTable(tid){const d=doc();return {...S.profile.table,...d.tables[tid],cells:{...S.profile.table.cells,...d.tables[tid]?.cells}}}
function tableHtml(t){const s=effectiveTable(t.id),active=S.mode==='after'&&s.enabled;const rows=t.rows;const cellrows=rows.map((row,ri)=>{let col=0;return '<tr>'+row.map((c,ci)=>{const thiscol=col;col+=c.span;if(c.merge==='continue')return '';let rowspan=1;if(c.merge==='restart'){for(let j=ri+1;j<rows.length;j++){let pos=0,match=null;for(const below of rows[j]){if(pos===thiscol)match=below;pos+=below.span}if(match?.merge==='continue')rowspan++;else break}}const cs=S.mode==='after'?s.cells?.[c.key]||{}:{};let css=[];if(active){css.push(`font-family:"${safeFont(s.font)}","${safeFont(s.latin)}",serif`,`font-size:${s.size*1.333*S.zoom}px`,`text-align:${s.cellAlign}`,`vertical-align:${s.valign==='center'?'middle':s.valign}`,`padding:${s.paddingTop*S.zoom}px ${s.paddingRight*S.zoom}px ${s.paddingBottom*S.zoom}px ${s.paddingLeft*S.zoom}px`,`line-height:${s.line}`);if(s.rowHeight)css.push(`height:${s.rowHeight*1.333*S.zoom}px`);if(ri<s.headerRows)css.push(`background:#${s.headerFill}`,`font-weight:${s.headerBold?'700':'400'}`);if(s.borderMode==='none')css.push('border:0');if(s.borderMode==='grid')css.push(`border:${s.borderSize}px solid #${s.borderColor}`);if(s.borderMode==='three'){css.push('border:0');if(ri===0)css.push(`border-top:${s.borderSize}px solid #${s.borderColor}`);if(ri+rowspan>=s.headerRows&&ri<s.headerRows||ri+rowspan===rows.length)css.push(`border-bottom:${s.borderSize}px solid #${s.borderColor}`)}if(s.borderMode==='custom'){for(const edge of ['top','bottom','left','right']){const outer=edge==='top'&&ri===0||edge==='bottom'&&ri+rowspan===rows.length||edge==='left'&&ci===0||edge==='right'&&ci===row.length-1;const kind=s.borders[outer?edge:['top','bottom'].includes(edge)?'insideH':'insideV'];css.push(`border-${edge}:${kind==='nil'?'0':`${s.borderSize}px ${kind==='single'?'solid':kind} #${s.borderColor}`}`)}}}
if(cs.fill)css.push(`background:#${cs.fill}`);if(cs.align)css.push(`text-align:${cs.align}`);if(cs.valign)css.push(`vertical-align:${cs.valign==='center'?'middle':cs.valign}`);if(cs.size)css.push(`font-size:${cs.size*1.333*S.zoom}px`);if(cs.font||cs.latin)css.push(`font-family:"${safeFont(cs.font||s.font)}","${safeFont(cs.latin||s.latin)}",serif`);if(cs.bold!==undefined&&cs.bold!==null)css.push(`font-weight:${cs.bold?'700':'400'}`);if(cs.italic!==undefined&&cs.italic!==null)css.push(`font-style:${cs.italic?'italic':'normal'}`);if(cs.borders)for(const [edge,kind] of Object.entries(cs.borders))css.push(`border-${edge}:${kind==='nil'?'0':`${cs.borderSize||.75}px ${kind==='single'?'solid':kind} #${cs.borderColor||'000000'}`}`);const texts=c.paragraphs.map(id=>dpara(id)?.text).filter(Boolean);let body=texts.map(t=>`<p>${esc(t)}</p>`).join('')||esc(c.text);for(const pid of c.paragraphs){const p=dpara(pid);if(p)for(const eid of p.equations){const eq=doc().model.equations.find(e=>e.id===eid);if(eq)body+=mathHtml(eq)}}body+=c.nested.map(id=>tableHtml(doc().model.tables.find(t=>t.id===id))).join('');return `<td colspan="${c.span}" rowspan="${rowspan}" data-cell="${c.key}" data-table="${t.id}" class="${S.tid===t.id&&S.cell===c.key?'selected':''}" style="${esc(css.join(';'))}">${body}</td>`}).join('')+'</tr>'}).join('');const widths=active&&s.columns?s.columns.split(',').map(Number):t.widths;const total=widths.reduce((a,b)=>a+b,0)||1;return `<div class="doc-table-wrap ${S.tid===t.id&&S.tab==='tables'?'selected':''}" data-table="${t.id}"><div class="table-label">表格 ${Number(t.id.slice(1))+1} · ${rows.length} 行 / ${t.columns} 列</div><table class="doc-table" style="width:${active?s.width:100}%;margin-left:${active&&s.align==='left'?'0':'auto'};margin-right:${active&&s.align==='right'?'0':'auto'};table-layout:${active&&s.layout==='fixed'?'fixed':'auto'}"><colgroup>${widths.map(w=>`<col style="width:${w/total*100}%">`).join('')}</colgroup><tbody>${cellrows}</tbody></table></div>`}
function dpara(id){return doc()?.model.paragraphs.find(p=>p.id===id)}
function insertionHtml(x){return `<div class="inserted-equation" data-insertion="${x.id}"><small>新增原生公式 · 点击编辑</small><span class="formula-view"><math-field read-only>${esc(x.latex)}</math-field></span></div>`}
function renderPreview(){const d=doc(),scroller=$('previewScroll'),top=scroller.scrollTop,failed=d?.report?.checks?.filter(c=>c.status==='fail').length||0;$('docTitle').textContent=d?d.name.replace(/\.docx$/i,''):'从一份文档开始';$('docMeta').textContent=d?`${d.model.counts.paragraphs} 个段落 · ${d.model.counts.tables} 个表格 · ${d.model.counts.equations} 个原生公式`:'打开 DOCX，或载入示例体验完整流程';$('dirtyBadge').textContent=isResultStale(d)?'先前设置 · 可重新排版':failed?'检查未通过 · 请复核':d?.report?'已检查 · 可导出':d?'设置待应用':'尚未导入';$('dirtyBadge').className='badge'+(d?.report&&!failed?' done':'');document.querySelectorAll('[data-mode]').forEach(b=>b.classList.toggle('active',b.dataset.mode===S.mode));$('paper').style.setProperty('--zoom',S.zoom);
if(!d){$('paper').innerHTML='<div class="empty"><div class="empty-icon">¶</div><strong>让文档有自己的秩序</strong>精确调整各级标题、段落、表格与公式<br><button class="button primary" data-empty-sample>打开演示文档</button><p class="help">也可以将 DOCX 拖到这里</p></div>';return}
let html='<div class="paper-label">'+(S.mode==='before'?'ORIGINAL STRUCTURE':'FORMATTING PREVIEW')+' / '+(d.name==='演示文档.docx'?'DEMO':'DOCX')+'</div>';for(const block of d.model.blocks){if(block.kind==='paragraph'){const p=dpara(block.id);if(p)html+=paragraphHtml(p);if(S.mode==='after')html+=d.insertions.filter(x=>x.after===block.id).map(insertionHtml).join('')}else if(block.kind==='table'){const t=d.model.tables.find(t=>t.id===block.id);if(t)html+=tableHtml(t)}else html+=`<div class="help">${esc(block.text)}</div>`}if(S.mode==='after')html+=d.insertions.filter(x=>!x.after).map(insertionHtml).join('');$('paper').innerHTML=html;scroller.scrollTop=top}

