function input(key,label,value,target='style',opts={}){const type=opts.type||'number';if(opts.font)return `<div class="field ${opts.wide?'wide':''}"><span>${label}</span><div class="font-input-row"><input data-setting="${key}" data-target="${target}" type="text" value="${esc(value??'')}" placeholder="输入字体名，或打开字体库" spellcheck="false"><button type="button" class="font-picker-open" data-font-open title="浏览字体库">选择</button></div><small class="font-availability" data-font-name="${esc(value||'')}">${esc(['equation','equationLocal'].includes(target)?mathFontAvailability(value):fontAvailability(value))}</small>${opts.help?`<small>${opts.help}</small>`:''}</div>`;const list=key==='size'?'fontSizes':'';return `<label class="field ${opts.wide?'wide':''}">${label}<input data-setting="${key}" data-target="${target}" type="${type}" value="${esc(value??'')}" ${type==='number'?`min="${opts.min??0}" max="${opts.max??500}" step="${opts.step??.5}"`:''} ${list?`list="${list}"`:''} ${opts.color?'data-color="1"':''} ${opts.placeholder?`placeholder="${esc(opts.placeholder)}"`:''}>${opts.help?`<small>${opts.help}</small>`:''}</label>`}
