function renderFontPicker(){const list=$('fontPickerList'),q=$('fontSearch').value.trim().toLocaleLowerCase(),manual=[...new Set([...Object.values(S.profile.styles).flatMap(s=>[s.font,s.latin]),...S.docs.flatMap(d=>Object.values(d.overrides).flatMap(s=>[s.font,s.latin])),fontPickerTarget?.value].filter(Boolean))].filter(n=>!fontCatalog.installed.includes(n)&&!fontCatalog.office.includes(n)&&!fontCatalog.common.includes(n));const sections=[...(fontPickerTarget&&['equation','equationLocal'].includes(fontPickerTarget.dataset.target)?[{title:'本机检测到数学排版表的字体',items:fontCatalog.installed.filter(n=>fontCatalog.mathStatus?.[n]==='math'),tag:'数学字体，目标软件仍需复核'}]:[]),{title:`本机已检测字体 · ${fontCatalog.installed.length}`,items:fontCatalog.installed,tag:'已检测'},{title:`Office 云字体目录 · ${fontCatalog.office.length} 个名称`,items:fontCatalog.office,tag:'目录名称，未验证'},{title:'常用字体名称（未验证）',items:fontCatalog.common.filter(n=>!fontCatalog.installed.includes(n)),tag:'常用名，未验证'},{title:'手工输入的名称（未验证）',items:manual,tag:'手工名，未验证'}];list.innerHTML=sections.map(section=>{const items=section.items.filter(name=>!q||name.toLocaleLowerCase().includes(q));return `<section class="font-picker-section"><h3>${esc(section.title)} <small>${items.length} 个匹配</small></h3>${items.length?`<div class="font-picker-options">${items.map(name=>`<button type="button" role="option" class="font-option" data-font-value="${esc(name)}"><span>${esc(name)}</span><small>${section.tag}</small></button>`).join('')}</div>`:`<p class="font-picker-empty">没有匹配字体</p>`}</section>`}).join('');$('fontPickerHint').textContent=fontSummary()+' 云字体使用情况取决于 Microsoft 365 账户、Office 版本和网络。'}
